INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'la-gran-carrera-de-la-mimica-scout', 'La Gran Carrera de la Mímica Scout', 'Dinámica de relevos expresivos y adiestramiento de patrulla donde los scouts representan técnicas de campamento mediante mímica silenciosa.', '<h2>📜 Descripción de La Gran Carrera de la Mímica Scout</h2>
<p><b>La Gran Carrera de la Mímica Scout</b> es una dinámica de relevos, expresión corporal dramática y adiestramiento en técnicas scouts. En esta actividad, las patrullas se organizan en filas paralelas. El primer corredor corre hacia el dirigente, recibe en secreto una tarjeta con una acción scout de campamento (ej. <i>''Armar una carpa canadiense''</i>, <i>''Hacer un nudo llano''</i>, <i>''Encender una fogata pirámide''</i> o <i>''Cocinar en cocinilla de gas''</i>) y regresa corriendo a su equipo para representarla mediante gestos y mímica silenciosa. Tan pronto como un compañero adivina la acción, el siguiente corredor sale a recibir su propia consigna.</p>
<p>Esta dinámica refuerza el conocimiento de la Ley Scout, la agilidad de interpretación y la cohesión de patrulla en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega La Gran Carrera de la Mímica Scout?</h2>
<p>Para desarrollar la dinámica con ritmo y dinamismo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Línea de Salida:</b> Las patrullas se forman en filas indias tras la línea de partida. A 15 metros se ubica la estación de los dirigentes con el mazo de tarjetas secretas.</li>
  <li><b>Carrera y Secreto:</b> A la señal del silbato, el primer scout corre hacia la estación, lee la tarjeta asignada y regresa a toda velocidad hasta su patrulla.</li>
  <li><b>Mímica Silenciosa:</b> El corredor actúa la técnica o valor scout utilizando exclusivamente gestos corporales, señas y ademanes sin emitir sonidos ni palabras.</li>
  <li><b>Adivinanza e Impulso:</b> Cuando algún integrante de la patrulla adivina la acción exacta en voz alta, el dirigente de línea valida el acierto y el segundo participante corre a buscar la siguiente tarjeta.</li>
  <li><b>Cierre de Relevos:</b> La patrulla que complete primero todas sus tarjetas de mímica scout se adjudica la victoria de la carrera.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de La Gran Carrera de la Mímica Scout</h2>
<p>La carrera premia la fidelidad técnica y la velocidad de equipo en el Tally:</p>
<ul>
  <li><b>Mayor Velocidad de Relevos:</b> Otorgar 5 puntos a la patrulla o seisena que complete todas las tarjetas en menor tiempo.</li>
  <li><b>Fidelidad Gestual Técnica:</b> Otorgar 3 puntos al corredor que demuestre la representación más precisa de los nudos o construcciones scouts.</li>
  <li><b>Espíritu de Patrulla:</b> Otorgar 3 puntos al equipo que mantenga el aliento más entusiasta durante las actuaciones.</li>
</ul>', '/uploads/la-gran-carrera-de-la-mimica-scout.webp', 'publicado', '{"areas": ["carácter", "creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Exterior", "Interior"], "materiales": ["Tarjetas con Acciones Scouts"], "objetivos": ["Construir el proyecto de vida en base a la Ley y la Promesa Scout", "Desarrollar la agilidad mental y la expresión corporal", "Reforzar las técnicas scouts de campamento", "Fomentar la cohesión en las filas de patrulla"], "justificacion_areas": "La Gran Carrera de la Mímica Scout desarrolla el carácter al afianzar el compromiso personal con los valores de la Ley y la Promesa expresados en la vivencia scout cotidiana. Estimula la creatividad al requerir la adaptación dramática de técnicas de campamento a un lenguaje no verbal inmediato. Fortalece la sociabilidad al afianzar la lealtad y el apoyo mutuo en las competencias de relevos.", "variaciones": "<b>Mímica de Primeros Auxilios:</b> Representar exclusivamente técnicas de vendaje y traslado de heridos en campamento.<br><b>Mímica de Historia Scout:</b> Representar episodios de la vida de Baden-Powell o del primer campamento de Brownsea.<br><b>Relevo Mudo de Nudos:</b> El corredor representa el nudo con mímica y el adivinador debe correr a ejecutarlo físicamente con un piola.", "recomendaciones": "Delimitar un área de carrera plana y libre de obstáculos para prevenir caídas. Verificar que las tarjetas contengan acciones scout claras y acordes al nivel de progresión de cada unidad.", "objetivos_educativos": [{"id": "eba5dac5-e1aa-498d-8d94-9655162890e5", "area": "Carácter", "unidad": "Manada", "texto": "Entiendo que es bueno que tenga metas que me ayuden a ser cada día mejor.", "como_se_cumple": "Esforzándome en la carrera para ayudar a mi seisena a alcanzar la meta con alegría."}, {"id": "feeaf72d-4c33-4edd-8513-000a659d0491", "area": "Carácter", "unidad": "Manada", "texto": "Me propongo tareas y metas que me ayudan a superar mis defectos.", "como_se_cumple": "Superando el temor a actuar en público al representar técnicas scouts ante el grupo."}, {"id": "a8667e56-d5f7-4f7b-b666-06c0b0d0d430", "area": "Carácter", "unidad": "Compañía", "texto": "Conozco y comprendo la Ley y la Promesa Guía.", "como_se_cumple": "Demostrando comprensión práctica de la Ley y la Promesa en las escenificaciones de patrulla."}, {"id": "2b89163c-b44c-4a1e-b71d-f5e9e2e87abd", "area": "Carácter", "unidad": "Compañía", "texto": "Comprendo que lo que me piden la Ley y la Promesa Guía es importante para mi vida.", "como_se_cumple": "Reflejando la importancia de las normas scouts en mi comportamiento durante la carrera."}, {"id": "58730385-703d-4410-b7aa-757c2e387e27", "area": "Carácter", "unidad": "Tropa", "texto": "Conozco y comprendo la Ley y la Promesa Scout.", "como_se_cumple": "Interiorizando el espíritu de la Promesa mediante la mímica de acciones de servicio."}, {"id": "631f013b-4c64-4c61-bd35-b9965f0c5e8e", "area": "Carácter", "unidad": "Tropa", "texto": "Comprendo que lo que me piden la Ley y la Promesa Scout es importante para mi vida.", "como_se_cumple": "Construyendo mi identidad scout sobre el testimonio alegre y constante de la Ley."}, {"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando con atención los gestos del corredor para adivinar la técnica scout."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Adivinando con agilidad mental las señas kinésicas representadas por el compañero."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "unidad": "Compañía", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Proclamando en voz alta las soluciones gestuales para dinamizar el relevo."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Analizando la expresión corporal para traducirla a términos técnicos de campamento."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "unidad": "Tropa", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Aportando rapidez de respuesta en las adivinanzas de la patrulla."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Diseñando estrategias dramáticas eficientes para comunicar ideas complejas."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando con lealtad la línea de salida y las normas del relevo."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Respetando los turnos de salida de cada corredor en la seisena."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Favoreciendo un clima de competencia justa, integración y buen trato."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Apoyando con entusiasmo a las compañeras durante su turno de mímica."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Cumpliendo honestamente las consignas de silencio absoluto durante la mímica."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la cohesión y lealtad de la Tropa en competencias colectivas."}]}'::jsonb, NOW(), NOW(), NULL, NULL
